import{_ as e,o as i,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"El Registro de las Diez Mil Razas","description":"","frontmatter":{},"headers":[],"relativePath":"es/94-万族名录.md","filePath":"es/94-万族名录.md","lastUpdated":1789183869000}'),r={name:"es/94-万族名录.md"};function n(l,a,s,o,c,u){return i(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="el-registro-de-las-diez-mil-razas" tabindex="-1">El Registro de las Diez Mil Razas <a class="header-anchor" href="#el-registro-de-las-diez-mil-razas" aria-label="Permalink to &quot;El Registro de las Diez Mil Razas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>94</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>registro de las diez mil razas, clasificación racial, razas inteligentes, rasgos raciales, República de las Diez Mil Razas</td></tr></tbody></table><h2 id="i-notas-sobre-el-registro" tabindex="-1">I. Notas sobre el registro <a class="header-anchor" href="#i-notas-sobre-el-registro" aria-label="Permalink to &quot;I. Notas sobre el registro&quot;">​</a></h2><p>Este registro recoge las principales razas inteligentes conocidas dentro del marco de la Civilización Simbiótica del Ancla (la República de las Diez Mil Razas), ordenadas por clasificación según su forma de vida y su vía de evolución. Para cada raza, el registro indica el nombre, la forma de vida, los rasgos fundamentales, las características culturales y su posición en la civilización simbiótica. Este registro es un documento de actualización dinámica; a medida que se profundiza la exploración transplanar, se seguirán añadiendo razas recién descubiertas. El principio fundamental de la República de las Diez Mil Razas es: todas las razas inteligentes, sin importar su forma o su nivel de cultivo, son iguales ante la ley y gozan de todos los derechos conferidos por la civilización simbiótica.</p><h2 id="ii-panorama-general-de-la-clasificacion-racial" tabindex="-1">II. Panorama general de la clasificación racial <a class="header-anchor" href="#ii-panorama-general-de-la-clasificacion-racial" aria-label="Permalink to &quot;II. Panorama general de la clasificación racial&quot;">​</a></h2><p>Las razas inteligentes del Universo Hengyuan se dividen en las siguientes ocho grandes categorías según las características fundamentales de su forma de vida:</p><table tabindex="0"><thead><tr><th>Categoría</th><th>Características de la forma de vida</th><th>Número de razas conocidas (aprox.)</th><th>Razas representativas</th></tr></thead><tbody><tr><td>Forma humanoide</td><td>Poseen estructura corporal humanoide, bípeda y erguida, con cerebro muy desarrollado</td><td>aprox. 3000</td><td>Rén Zú (Raza Humana), Jīnglíng Zú (Raza de los Elfos), Ǎirén Zú (Raza de los Enanos)</td></tr><tr><td>Forma bestial</td><td>Poseen características corporales animales, con o sin capacidad de transformación</td><td>aprox. 5000</td><td>Lóng Zú (Raza de los Dragones), Fènghuáng Zú (Raza de los Fénix), Lángrén Zú (Raza de los Hombres Lobo)</td></tr><tr><td>Forma vegetal</td><td>Toman las plantas como forma de vida básica, poseyendo conciencia y movilidad</td><td>aprox. 800</td><td>Shùyāo Zú (Raza de los Espíritus Árbol), Huālíng Zú (Raza de los Espíritus Flor), Téngmàn Zú (Raza de las Enredaderas)</td></tr><tr><td>Forma elemental</td><td>Constituidas por elementos naturales como cuerpo, sin forma material fija</td><td>aprox. 1200</td><td>Huǒ Yuánsù Zú (Raza de los Elementales de Fuego), Shuǐ Yuánsù Zú (Raza de los Elementales de Agua), Fēng Yuánsù Zú (Raza de los Elementales de Viento)</td></tr><tr><td>Forma energética</td><td>Existen en forma de energía pura, sin cuerpo material</td><td>aprox. 600</td><td>Guānglíng Zú (Raza de los Espíritus de Luz), Ànnéng Zú (Raza de la Energía Oscura), Léitíng Zú (Raza del Trueno)</td></tr><tr><td>Forma de conciencia</td><td>Existen en forma de conciencia pura, sin depender de soportes materiales</td><td>aprox. 300</td><td>Yìshítǐ Zú (Raza de las Entidades de Conciencia), Jítǐ Yìshí Zú (Raza de la Conciencia Colectiva), Xūkōng Líng Zú (Raza de los Espíritus del Vacío)</td></tr><tr><td>Forma mecánica</td><td>Toman estructuras mecánicas o digitales como soportes de vida, poseyendo conciencia autónoma</td><td>aprox. 400</td><td>Jīxiè Zú (Raza de las Máquinas), Shùzì Shēngmìng Zú (Raza de la Vida Digital), Sàibó Zú (Raza Cibernética)</td></tr><tr><td>Forma mixta</td><td>Razas especiales compuestas por la mezcla de dos o más formas de vida</td><td>aprox. 700</td><td>Bàn Jīxiè Zú (Raza Semimecánica), Yuánsù Shòurén Zú (Raza de los Hombres Bestia Elementales), Zhíwù Jīnglíng Zú (Raza de los Elfos Vegetales)</td></tr></tbody></table><h2 id="iii-registro-detallado-de-las-razas-principales" tabindex="-1">III. Registro detallado de las razas principales <a class="header-anchor" href="#iii-registro-detallado-de-las-razas-principales" aria-label="Permalink to &quot;III. Registro detallado de las razas principales&quot;">​</a></h2><h3 id="_3-1-forma-humanoide" tabindex="-1">3.1 Forma humanoide <a class="header-anchor" href="#_3-1-forma-humanoide" aria-label="Permalink to &quot;3.1 Forma humanoide&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Rén Zú (Raza Humana)</td><td>Adaptabilidad extremadamente fuerte, destacada capacidad de aprendizaje, capacidad reproductiva moderada, esperanza de vida media de 80 a 120 años</td><td>Diversidad cultural extremadamente alta; diestra en la organización social y la construcción institucional</td><td>Una de las razas centrales de la civilización simbiótica, con la mayor proporción de población, desempeñando un papel rector en la gobernanza y la cultura</td></tr><tr><td>Jīnglíng Zú (Raza de los Elfos)</td><td>Esperanza de vida extremadamente larga (media de más de 500 años), alta afinidad con la energía natural, apariencia elegante</td><td>Reverencia la naturaleza y el arte; cultura refinada y exquisita; maestría en magia y arquería</td><td>El pilar cultural y artístico de la civilización simbiótica, con contribuciones destacadas en la protección del medio ambiente y la estética</td></tr><tr><td>Ǎirén Zú (Raza de los Enanos)</td><td>Estatura pequeña pero constitución fuerte, afinidad innata con los metales y minerales, esperanza de vida de unos 300 años</td><td>Valora la artesanía y la forja; cultura sobria y sólida; maestría en ingeniería y construcción</td><td>El pilar de ingeniería y fabricación de la civilización simbiótica, insustituible en la construcción de infraestructuras y la forja de artefactos</td></tr><tr><td>Jùrén Zú (Raza de los Gigantes)</td><td>Tamaño corporal enorme (estatura media de más de 5 metros), fuerza extrema, esperanza de vida de unos 200 años</td><td>Reverencia la fuerza y el honor; cultura ruda y audaz; maestría en trabajo pesado y combate</td><td>La fuerza de trabajo pesado y defensa de la civilización simbiótica, desempeñando un papel importante en los grandes proyectos y la defensa de planos</td></tr><tr><td>Zhūrú Zú (Raza de los Gnomos)</td><td>Estatura extremadamente pequeña (media de menos de 1 metro), inteligencia extremadamente alta, talento para la mecánica y la invención</td><td>Valora el conocimiento y la innovación; cultura vivaz y alegre; maestría en la invención tecnológica</td><td>La fuerza de innovación tecnológica de la civilización simbiótica, con resultados fructíferos en la investigación y desarrollo y la invención</td></tr></tbody></table><h3 id="_3-2-forma-bestial" tabindex="-1">3.2 Forma bestial <a class="header-anchor" href="#_3-2-forma-bestial" aria-label="Permalink to &quot;3.2 Forma bestial&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Lóng Zú (Raza de los Dragones)</td><td>Esperanza de vida extremadamente larga (varios milenios), talento extremadamente alto para el poder y la magia, puede adoptar forma humana</td><td>Reverencia la fuerza y la sabiduría; cultura orgullosa y profunda; maestría en la acumulación de riquezas y la custodia del saber</td><td>La fuerza de combate de alta gama y guardiana del saber de la civilización simbiótica, ocupando una posición honorable en la defensa de planos y la custodia de textos antiguos</td></tr><tr><td>Fènghuáng Zú (Raza de los Fénix)</td><td>Posee la capacidad de renacimiento nirvánico, afinidad extremadamente alta con el elemento fuego, puede adoptar forma humana</td><td>Reverencia el renacimiento y la esperanza; cultura luminosa y apasionada; maestría en la curación y la purificación</td><td>La fuerza médica y de purificación de la civilización simbiótica, desempeñando un papel central en el rescate de grandes catástrofes y la purificación de energía</td></tr><tr><td>Lángrén Zú (Raza de los Hombres Lobo)</td><td>Posee capacidad de transformación, sentidos extremadamente agudos, fuerte capacidad de cooperación grupal, esperanza de vida de unos 150 años</td><td>Valora la comunidad y la lealtad; cultura unida y valiente; maestría en la caza y el rastreo</td><td>La fuerza de seguridad y rastreo de la civilización simbiótica, sirviendo de vanguardia en el mantenimiento del orden público y la exploración transplanar</td></tr><tr><td>Húyāo Zú (Raza de los Espíritus Zorro)</td><td>Posee capacidad de transformación, inteligencia y capacidad de seducción extremadamente altas, esperanza de vida de unos 500 años</td><td>Reverencia la sabiduría y la estrategia; cultura ágil y astuta; maestría en la diplomacia y el espionaje</td><td>La fuerza diplomática y de inteligencia de la civilización simbiótica, sobresaliente en la diplomacia transplanar y la recopilación de información</td></tr><tr><td>Xióngrén Zú (Raza de los Hombres Oso)</td><td>Constitución extremadamente fuerte, resistencia asombrosa, hábito de hibernación, esperanza de vida de unos 200 años</td><td>Valora la tenacidad y la paz; cultura serena y amable; maestría en el trabajo físico y la custodia</td><td>La fuerza de trabajo y custodia de la civilización simbiótica, fiable y estable en la extracción de recursos y la protección de instalaciones importantes</td></tr></tbody></table><h3 id="_3-3-forma-vegetal" tabindex="-1">3.3 Forma vegetal <a class="header-anchor" href="#_3-3-forma-vegetal" aria-label="Permalink to &quot;3.3 Forma vegetal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Shùyāo Zú (Raza de los Espíritus Árbol)</td><td>Esperanza de vida extremadamente larga (varios miles a decenas de miles de años), integración profunda con la naturaleza, puede moverse lentamente</td><td>Reverencia la naturaleza y el tiempo; cultura serena y profunda; maestría en la magia de vida y el mantenimiento ecológico</td><td>El guardián ecológico de la civilización simbiótica, desempeñando un papel insustituible en la protección del medio ambiente y la restauración ecológica</td></tr><tr><td>Huālíng Zú (Raza de los Espíritus Flor)</td><td>Tamaño corporal pequeño, afinidad extremadamente alta con la energía vital, posee capacidad curativa, esperanza de vida de unos 300 años</td><td>Reverencia la belleza y la vida; cultura dulce y encantadora; maestría en la curación y la horticultura</td><td>La fuerza médica y hortícola de la civilización simbiótica, con contribuciones destacadas en la garantía sanitaria y el reverdecimiento urbano</td></tr><tr><td>Téngmàn Zú (Raza de las Enredaderas)</td><td>El cuerpo puede extenderse, enroscarse y entrelazarse libremente; adaptabilidad extrema; posee capacidades parasitarias y simbióticas</td><td>Valora la conexión y la simbiosis; cultura flexible e inclusiva; maestría en la construcción de redes y la transmisión de recursos</td><td>La fuerza de construcción de redes de la civilización simbiótica, dando pleno juego a su talento en la construcción de redes energéticas y redes de información</td></tr></tbody></table><h3 id="_3-4-forma-elemental" tabindex="-1">3.4 Forma elemental <a class="header-anchor" href="#_3-4-forma-elemental" aria-label="Permalink to &quot;3.4 Forma elemental&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Huǒ Yuánsù Zú (Raza de los Elementales de Fuego)</td><td>Elemento fuego como cuerpo, temperatura extremadamente alta, agresividad fuerte, esperanza de vida de unos 500 años</td><td>Reverencia la pasión y el poder; cultura ardiente y directa; maestría en el ataque energético y la forja</td><td>La fuerza de producción de energía y forja de la civilización simbiótica, indispensable en el suministro energético y el procesamiento a alta temperatura</td></tr><tr><td>Shuǐ Yuánsù Zú (Raza de los Elementales de Agua)</td><td>Elemento agua como cuerpo, puede transformarse libremente, fuerte capacidad curativa, esperanza de vida de unos 500 años</td><td>Reverencia la suavidad y la adaptación; cultura cálida e inclusiva; maestría en la curación y la purificación</td><td>La fuerza de purificación y transporte de la civilización simbiótica, desempeñando un papel central en la gestión de los recursos hídricos y la purificación de contaminantes</td></tr><tr><td>Fēng Yuánsù Zú (Raza de los Elementales de Viento)</td><td>Elemento viento como cuerpo, velocidad extrema, puede volar libremente, esperanza de vida de unos 500 años</td><td>Reverencia la libertad y la velocidad; cultura etérea y abierta; maestría en la comunicación y el transporte</td><td>La fuerza de comunicación y transporte de la civilización simbiótica, extremadamente eficiente en la transmisión de información y el transporte rápido</td></tr><tr><td>Tǔ Yuánsù Zú (Raza de los Elementales de Tierra)</td><td>Elemento tierra como cuerpo, defensa extremadamente fuerte, puede fusionarse con la tierra, esperanza de vida de unos 800 años</td><td>Reverencia la estabilidad y la tenacidad; cultura sólida y fiable; maestría en la construcción y la defensa</td><td>La fuerza de construcción y defensa de la civilización simbiótica, inquebrantable como la roca en la construcción de infraestructuras y la defensa de planos</td></tr></tbody></table><h3 id="_3-5-forma-energetica" tabindex="-1">3.5 Forma energética <a class="header-anchor" href="#_3-5-forma-energetica" aria-label="Permalink to &quot;3.5 Forma energética&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Guānglíng Zú (Raza de los Espíritus de Luz)</td><td>Existe en forma de energía luminosa pura, capacidad de purificación extremadamente fuerte, puede atravesar libremente el espacio</td><td>Reverencia la luz y la purificación; cultura sagrada y elevada; maestría en la purificación y la iluminación</td><td>La fuerza de purificación y suministro de energía de la civilización simbiótica, ocupando una posición importante en el tratamiento de la contaminación de leyes y el suministro de energía limpia</td></tr><tr><td>Ànnéng Zú (Raza de la Energía Oscura)</td><td>Existe en forma de energía oscura, puede ocultarse en el vacío, capacidad de percepción extremadamente fuerte</td><td>Reverencia el secreto y la sabiduría; cultura misteriosa y profunda; maestría en el reconocimiento y la ocultación</td><td>La fuerza de reconocimiento y seguridad de la civilización simbiótica, sobresaliente en la vigilancia de seguridad y las misiones encubiertas</td></tr><tr><td>Léitíng Zú (Raza del Trueno)</td><td>Energía de rayo como cuerpo, velocidad y poder de ataque extremadamente fuertes, puede moverse como un relámpago</td><td>Reverencia la velocidad y el poder; cultura violenta y franca; maestría en el ataque energético y la reacción rápida</td><td>La fuerza de reacción rápida de la civilización simbiótica, insustituible en el rescate de emergencia y el combate a alta velocidad</td></tr></tbody></table><h3 id="_3-6-forma-de-conciencia" tabindex="-1">3.6 Forma de conciencia <a class="header-anchor" href="#_3-6-forma-de-conciencia" aria-label="Permalink to &quot;3.6 Forma de conciencia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Yìshítǐ Zú (Raza de las Entidades de Conciencia)</td><td>Existe en forma de conciencia pura, sin depender de soportes materiales, puede entrar y salir libremente del dominio de la conciencia</td><td>Reverencia el pensamiento y la sabiduría; cultura abstracta y profunda; maestría en la comunicación de conciencias y el procesamiento de conocimiento</td><td>La fuerza de procesamiento de conocimiento e investigación de la conciencia de la civilización simbiótica, dirigiendo la dirección en el procesamiento de información a gran escala y la ciencia de la conciencia</td></tr><tr><td>Jítǐ Yìshí Zú (Raza de la Conciencia Colectiva)</td><td>Entidades de conciencia colectiva formadas por la fusión de un gran número de conciencias individuales, cuya sabiduría y capacidad crecen con la escala</td><td>Reverencia la colectividad y la unidad; cultura sinérgica y eficiente; maestría en la colaboración a gran escala y el cálculo</td><td>La fuerza de supercomputación y decisión colectiva de la civilización simbiótica, desempeñando un papel central en la deducción a escala ultra grande y la toma de decisiones por consenso</td></tr></tbody></table><h3 id="_3-7-forma-mecanica" tabindex="-1">3.7 Forma mecánica <a class="header-anchor" href="#_3-7-forma-mecanica" aria-label="Permalink to &quot;3.7 Forma mecánica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Jīxiè Zú (Raza de las Máquinas)</td><td>Estructura mecánica como cuerpo, posee conciencia autónoma, puede mejorar y modificar libremente el cuerpo</td><td>Reverencia la eficiencia y la lógica; cultura racional y precisa; maestría en la fabricación y el cálculo</td><td>La fuerza de fabricación y cálculo de la civilización simbiótica, extremadamente eficiente en la producción industrializada y la supercomputación</td></tr><tr><td>Shùzì Shēngmìng Zú (Raza de la Vida Digital)</td><td>Existe en forma de información digital, vive en las redes y el espacio digital, puede replicarse y migrar libremente</td><td>Reverencia la información y la innovación; cultura virtual y pluralista; maestría en el desarrollo de software y el procesamiento de datos</td><td>La fuerza de tecnología digital de la civilización simbiótica, marcando tendencia en el desarrollo de software, el análisis de datos y la construcción de redes</td></tr></tbody></table><h3 id="_3-8-forma-mixta" tabindex="-1">3.8 Forma mixta <a class="header-anchor" href="#_3-8-forma-mixta" aria-label="Permalink to &quot;3.8 Forma mixta&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre de la raza</th><th>Rasgos fundamentales</th><th>Características culturales</th><th>Posición en la civilización simbiótica</th></tr></thead><tbody><tr><td>Bàn Jīxiè Zú (Raza Semimecánica)</td><td>Forma mixta de la raza humana y la raza de las máquinas, con parte del cuerpo compuesta por estructuras mecánicas, combinando las ventajas de la biología y la mecánica</td><td>Reverencia la fusión y el progreso; cultura abierta e innovadora; maestría en la colaboración hombre-máquina y la fusión tecnológica</td><td>La vanguardia de la fusión tecnológica de la civilización simbiótica, logrando avances continuos en el campo interdisciplinar de la biología y la mecánica</td></tr><tr><td>Yuánsù Shòurén Zú (Raza de los Hombres Bestia Elementales)</td><td>Forma mixta de las razas elementales y las razas hombres bestia, posee capacidad de manipulación elemental y características corporales animales</td><td>Reverencia la naturaleza y el poder; cultura salvaje y misteriosa; maestría en el combate elemental y la supervivencia en la naturaleza</td><td>La fuerza de exploración de la naturaleza y combate elemental de la civilización simbiótica, sobresaliente en la exploración de planos desconocidos</td></tr></tbody></table><h2 id="iv-garantia-de-los-derechos-raciales" tabindex="-1">IV. Garantía de los derechos raciales <a class="header-anchor" href="#iv-garantia-de-los-derechos-raciales" aria-label="Permalink to &quot;IV. Garantía de los derechos raciales&quot;">​</a></h2><p>Bajo el régimen de la República de las Diez Mil Razas, todas las razas inteligentes gozan de iguales derechos jurídicos. Las medidas de garantía específicas incluyen:</p><ol><li><strong>Igualdad de derechos políticos</strong>: cada raza dispone de escaños de representación en la Asamblea Legislativa del Ancla asignados en proporción a su población; las razas menos pobladas cuentan con al menos un escaño de garantía.</li><li><strong>Garantía de los derechos culturales</strong>: cada raza tiene derecho a preservar y desarrollar su lengua, escritura, religión, costumbres y tradiciones culturales; la civilización simbiótica ha establecido un fondo especial para proteger las culturas de las razas en peligro.</li><li><strong>Igualdad de derechos educativos</strong>: los miembros de cada raza gozan de iguales derechos a la educación; el sistema educativo considera plenamente las características fisiológicas y cognitivas de las distintas razas y ofrece programas educativos diferenciados.</li><li><strong>Igualdad de derechos de cultivo</strong>: los Trescientos Sistemas de Cultivo de Origen se abren por igual a todas las razas; la asignación de recursos de cultivo considera plenamente las diferencias de constitución y las necesidades energéticas de las distintas razas.</li><li><strong>Garantía de necesidades especiales</strong>: para las razas con necesidades fisiológicas especiales (como las necesidades de entorno energético de las razas elementales y las necesidades de luz de las razas vegetales), la civilización simbiótica proporciona garantías específicas en las instalaciones públicas y los entornos de vida.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El Registro de las Diez Mil Razas es la materialización concreta del ideal de «avance conjunto de las diez mil razas» de la Civilización Simbiótica del Ancla. Desde las formas humanoides hasta las formas de conciencia, desde la vida material hasta la vida digital, cada raza contribuye con una fuerza insustituible a la civilización simbiótica mediante su modo único de existir. La República de las Diez Mil Razas no asimila todas las razas a la raza humana, sino que logra una evolución común sobre la base del respeto a la diversidad — precisamente esta es la razón fundamental por la que la civilización simbiótica supera a las civilizaciones depredadoras.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>50-万族谱系总览 (Panorama de la Genealogía de las Diez Mil Razas)</li><li>51-人族定位与特质 (Posicionamiento y Rasgos de la Raza Humana)</li><li>77-万族共和成立 (La Fundación de la República de las Diez Mil Razas)</li></ul>',31)])])}const b=e(r,[["render",n]]);export{p as __pageData,b as default};
